func sortPatternsByStrength[T any](items []T, key func(i int) (float64, int, string)) {
	sort.SliceStable(items, func(i, j int) bool {
		si, ri, idi := key(i)
		sj, rj, idj := key(j)
		if si != sj {
			return si > sj
		}
		if ri != rj {
			return ri > rj
		}
		return idi < idj
	})
}

